    'Intercom: keeps the chat messenger session and visitor identity.' => 'Intercom: ohranja sejo klepetalnika in identiteto obiskovalca.',
    'Invalid JSON format. Please import a valid cookie array.' => 'Neveljavna oblika JSON. Uvozite veljavno polje piškotkov.',
